import { useState } from 'react'
import './App.css'

function App() {
  const [display, setDisplay] = useState('0')
  const [previousValue, setPreviousValue] = useState(null)
  const [operation, setOperation] = useState(null)
  const [waitingForOperand, setWaitingForOperand] = useState(false)

  const inputDigit = (digit) => {
    if (waitingForOperand) {
      setDisplay(String(digit))
      setWaitingForOperand(false)
    } else {
      setDisplay(display === '0' ? String(digit) : display + digit)
    }
  }

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay('0.')
      setWaitingForOperand(false)
    } else if (display.indexOf('.') === -1) {
      setDisplay(display + '.')
    }
  }

  const clear = () => {
    setDisplay('0')
    setPreviousValue(null)
    setOperation(null)
    setWaitingForOperand(false)
  }

  const performOperation = (nextOperation) => {
    const inputValue = parseFloat(display)

    if (previousValue === null) {
      setPreviousValue(inputValue)
    } else if (operation) {
      const currentValue = previousValue || 0
      const newValue = calculate(currentValue, inputValue, operation)

      setDisplay(String(newValue))
      setPreviousValue(newValue)
    }

    setWaitingForOperand(true)
    setOperation(nextOperation)
  }

  const calculate = (firstValue, secondValue, operation) => {
    switch (operation) {
      case '+':
        return firstValue + secondValue
      case '-':
        return firstValue - secondValue
      case '×':
        return firstValue * secondValue
      case '÷':
        return firstValue / secondValue
      case '=':
        return secondValue
      default:
        return secondValue
    }
  }

  const toggleSign = () => {
    const newValue = parseFloat(display) * -1
    setDisplay(String(newValue))
  }

  const inputPercent = () => {
    const currentValue = parseFloat(display)
    if (currentValue === 0) return
    const newValue = currentValue / 100
    setDisplay(String(newValue))
  }

  return (
    <div className="calculator">
      <div className="calculator-display">{display}</div>
      <div className="calculator-keypad">
        <div className="input-keys">
          <div className="function-keys">
            <button className="calculator-key key-clear" onClick={clear}>
              {display !== '0' || previousValue !== null ? 'C' : 'AC'}
            </button>
            <button className="calculator-key key-sign" onClick={toggleSign}>±</button>
            <button className="calculator-key key-percent" onClick={inputPercent}>%</button>
          </div>
          <div className="digit-keys">
            <button className="calculator-key key-0" onClick={() => inputDigit(0)}>0</button>
            <button className="calculator-key key-dot" onClick={inputDecimal}>●</button>
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((digit) => (
              <button
                key={digit}
                className={`calculator-key key-${digit}`}
                onClick={() => inputDigit(digit)}
              >
                {digit}
              </button>
            ))}
          </div>
        </div>
        <div className="operator-keys">
          <button className="calculator-key key-divide" onClick={() => performOperation('÷')}>÷</button>
          <button className="calculator-key key-multiply" onClick={() => performOperation('×')}>×</button>
          <button className="calculator-key key-subtract" onClick={() => performOperation('-')}>−</button>
          <button className="calculator-key key-add" onClick={() => performOperation('+')}>+</button>
          <button className="calculator-key key-equals" onClick={() => performOperation('=')}>=</button>
        </div>
      </div>
    </div>
  )
}

export default App

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.calculator {
  width: 100%;
  max-width: 400px;
  background: #2d2d2d;
  border-radius: 20px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.calculator-display {
  background: #1a1a1a;
  color: #ffffff;
  font-size: 3rem;
  padding: 40px 30px;
  text-align: right;
  font-weight: 300;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  word-wrap: break-word;
  word-break: break-all;
  border-bottom: 1px solid #3d3d3d;
}

.calculator-keypad {
  display: flex;
  padding: 10px;
}

.input-keys {
  flex: 3;
}

.function-keys {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 10px;
}

.digit-keys {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  grid-template-areas:
    "key-1 key-2 key-3"
    "key-4 key-5 key-6"
    "key-7 key-8 key-9"
    "key-0 key-0 key-dot";
}

.key-0 {
  grid-area: key-0;
}

.operator-keys {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-left: 10px;
}

.calculator-key {
  background: #505050;
  border: none;
  color: #ffffff;
  font-size: 1.5rem;
  padding: 20px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 400;
  outline: none;
}

.calculator-key:hover {
  background: #606060;
  transform: scale(1.05);
}

.calculator-key:active {
  transform: scale(0.95);
}

.function-keys .calculator-key {
  background: #a6a6a6;
  color: #1a1a1a;
  font-weight: 500;
}

.function-keys .calculator-key:hover {
  background: #b6b6b6;
}

.operator-keys .calculator-key {
  background: #ff9500;
  font-size: 1.8rem;
  font-weight: 300;
}

.operator-keys .calculator-key:hover {
  background: #ffaa33;
}

.key-equals {
  background: #ff9500;
}

.key-equals:hover {
  background: #ffaa33;
}

.key-dot {
  font-size: 2rem;
  line-height: 1;
}

/* Responsive design */
@media (max-width: 480px) {
  .calculator {
    max-width: 100%;
    border-radius: 0;
  }

  .calculator-display {
    font-size: 2.5rem;
    padding: 30px 20px;
    min-height: 100px;
  }

  .calculator-key {
    font-size: 1.3rem;
    padding: 15px;
  }

  .operator-keys .calculator-key {
    font-size: 1.6rem;
  }
}

